package com.yessteveattribute.paper;
import com.yessteveattribute.core.config.LoadedConfiguration;
import com.yessteveattribute.core.config.YamlConfigLoader;
import com.yessteveattribute.core.runtime.*;
import org.bukkit.ChatColor; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.bukkit.plugin.ServicePriority; import org.bukkit.plugin.java.JavaPlugin;
import com.minebrowse.paper.api.MineBrowseUi;
import java.io.IOException; import java.nio.file.Files; import java.nio.file.Path; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
/** Paper 1.20.1 adapter for the platform-neutral YSA core. */
public final class YesSteveAttributePaper extends JavaPlugin {
 private final YamlConfigLoader loader=new YamlConfigLoader(); private final Map<UUID,Profile> profiles=new ConcurrentHashMap<>(); private volatile LoadedConfiguration configuration; private volatile String lastReload="未加载";
 private MineBrowseUi ui;
 private static final String DEBUG_UI="ysa_debug";
 @Override public void onEnable(){ saveTemplates(); if(!reloadConfiguration()){getLogger().severe("YSA 配置加载失败，插件保持禁用状态");getServer().getPluginManager().disablePlugin(this);return;} YsaCommand command=new YsaCommand(this); PluginCommand ysa=getCommand("ysa"); if(ysa!=null){ysa.setExecutor(command);ysa.setTabCompleter(command);} getServer().getServicesManager().register(PaperAttributeService.class,new PaperAttributeService(this),this,ServicePriority.Normal); registerDebugUi(); getLogger().info("YesSteveAttribute Paper 已启用 (Paper 1.20.1 API)"); }
 @Override public void onDisable(){ if(ui!=null){ui.unregisterMethod("ysa.debug.snapshot");ui.unregisterMethod("ysa.debug.config");for(Player p:new ArrayList<>(ui.viewers(DEBUG_UI)))ui.close(p);ui.unregisterUi(DEBUG_UI);} profiles.clear();}
 private void saveTemplates(){Path dir=getDataFolder().toPath();try{Files.createDirectories(dir);for(String name:List.of("attributes.yml","formulas.yml","roles.yml","levels.yml"))if(!Files.exists(dir.resolve(name)))saveResource(name,false);}catch(IOException ex){throw new IllegalStateException("无法创建配置目录",ex);}}
 public synchronized boolean reloadConfiguration(){LoadedConfiguration previous=configuration;try{LoadedConfiguration next=loader.load(getDataFolder().toPath());configuration=next;profiles.values().forEach(Profile::recalculate);lastReload="成功";return true;}catch(RuntimeException|IOException ex){configuration=previous;if(previous!=null){try{profiles.values().forEach(Profile::recalculate);}catch(RuntimeException ignored){getLogger().severe("YSA 回滚时玩家重算也失败: "+ignored.getMessage());}}lastReload="失败: "+ex.getMessage();getLogger().severe("YSA reload 失败，保留旧配置: "+ex.getMessage());return false;}}
 public LoadedConfiguration configuration(){LoadedConfiguration value=configuration;if(value==null)throw new IllegalStateException("YSA 配置尚未加载");return value;} public String lastReload(){return lastReload;} public Profile profile(Player player){return profiles.computeIfAbsent(player.getUniqueId(),id->new Profile(player));}
 void setRole(Player player,String role,int level){Profile p=profile(player);p.role=role;p.level=level;p.recalculate();}
 void setLevel(Player player,int level){Profile p=profile(player);p.level=Math.max(1,level);p.recalculate();}
 void setResource(Player player,String id,double value){Profile p=profile(player);ResourceState state=p.resources.get(id);if(state==null)throw new IllegalArgumentException("未知资源: "+id);p.resources.put(id,state.set(value));p.snapshot=ResourceCalculator.overlay(p.snapshot,p.resources);}
 boolean openDebugUi(Player player){return ui!=null && ui.hasClient(player) && ui.open(player,DEBUG_UI);}
 private void registerDebugUi(){try{ui=MineBrowseUi.get();Path folder=getDataFolder().toPath().resolve("ui/ysa_debug");Files.createDirectories(folder);for(String file:List.of("index.html","app.js","style.css")){if(!Files.exists(folder.resolve(file)))saveResource("ui/ysa_debug/"+file,false);}ui.registerUi(this,DEBUG_UI,folder,"YSA 服务端属性调试","ysa.debug");ui.registerMethod("ysa.debug.snapshot",(player,page,params)->debugSnapshot(player));ui.registerMethod("ysa.debug.config",(player,page,params)->debugConfig());getLogger().info("YSA 临时服务端调试界面已注册（EmpyreanUI/MineBrowse 页面适配）");}catch(Exception ex){ui=null;getLogger().warning("未注册 YSA 临时调试界面: "+ex.getMessage());}}
 private Map<String,Object> debugSnapshot(Player player){Profile p=profile(player);Map<String,Object> values=new LinkedHashMap<>();p.snapshot().all().forEach(values::put);Map<String,Object> resources=new LinkedHashMap<>();p.resources().forEach((id,s)->resources.put(id,Map.of("current",s.current(),"maximum",s.maximum(),"recovery",s.recovery(),"decay",s.decay())));return Map.of("schemaVersion",1,"serverAuthoritative",true,"player",player.getName(),"reload",lastReload,"values",values,"resources",resources);}
 private Map<String,Object> debugConfig(){Map<String,Object> attrs=new LinkedHashMap<>();configuration().getAttributes().getAttributes().forEach((id,d)->attrs.put(id,Map.of("group",d.getGroup(),"type",d.getType(),"unit",d.getUnit(),"default",d.getDefaultValue(),"visible",d.isVisible())));return Map.of("schemaVersion",1,"serverAuthoritative",true,"reload",lastReload,"attributes",attrs,"resources",configuration().getAttributes().getResources().keySet(),"roles",configuration().getRoles().getRoles().keySet());}
 public final class Profile { private final Player player; private String role=""; private int level=1; private Map<String,ResourceState> resources=new LinkedHashMap<>(); private AttributeSnapshot snapshot=new AttributeSnapshot(Map.of(),Map.of()); private Profile(Player player){this.player=player;recalculate();} public synchronized void recalculate(){AttributeSnapshot base=new PlayerAttributeCalculator().calculate(configuration(),role,level);resources=new LinkedHashMap<>(new ResourceCalculator().calculate(configuration(),base,level,currentValues(resources)));var derived=new DerivedAttributeCalculator().calculate(configuration(),base,level,resources);snapshot=ResourceCalculator.overlay(derived.snapshot(),resources);} private Map<String,Double> currentValues(Map<String,ResourceState> states){Map<String,Double> values=new HashMap<>();states.forEach((id,state)->values.put(id,state.current()));return values;} public Player player(){return player;} public synchronized String role(){return role;} public synchronized int level(){return level;} public synchronized AttributeSnapshot snapshot(){return snapshot;} public synchronized Map<String,ResourceState> resources(){return Map.copyOf(resources);} public synchronized ResourceConsumption.Result consume(Map<String,Double> costs){var result=ResourceConsumption.evaluate(resources,costs);if(result.accepted()){resources=new LinkedHashMap<>(result.after());snapshot=ResourceCalculator.overlay(snapshot,resources);}return result;} public synchronized CombatCalculator.Result calculateAttack(org.bukkit.entity.LivingEntity target,double multiplier,double roll,CombatDamageType type){AttributeSnapshot base=new PlayerAttributeCalculator().calculate(configuration(),role,level);Map<String,Double> targetValues=new LinkedHashMap<>();configuration().getAttributes().getAttributes().forEach((id,definition)->{if(definition.getDefaultValue() instanceof Number n)targetValues.put(id,n.doubleValue());});var armor=target.getAttribute(org.bukkit.attribute.Attribute.GENERIC_ARMOR);targetValues.put("护甲",armor==null?0D:armor.getValue());return new CombatCalculator().calculate(configuration(),base,level,snapshot,new AttributeSnapshot(targetValues,Map.of()),multiplier,roll,type);}}
}
